class ReSTXRayNode:
    def __init__(
        self,
        address: str,
        port: int,
        api_port: int,
        ssl_key: str,
        ssl_cert: str,
        usage_coefficient: float = 1,
    ):
        self.address = address
        self.port = port
        self.api_port = api_port
        self.ssl_key = ssl_key
        self.ssl_cert = ssl_cert
        self.usage_coefficient = usage_coefficient

        self._keyfile = string_to_temp_file(ssl_key)
        self._certfile = string_to_temp_file(ssl_cert)

        self.session = requests.Session()
        self.session.mount("https://", SANIgnoringAdaptor())
        self.session.cert = (self._certfile.name, self._keyfile.name)

        self._session_id = None
        self._rest_api_url = f"https://{self.address.strip('/')}:{self.port}"

        self._ssl_context = ssl.create_default_context()
        self._ssl_context.check_hostname = False
        self._ssl_context.verify_mode = ssl.CERT_NONE
        self._ssl_context.load_cert_chain(
            certfile=self.session.cert[0], keyfile=self.session.cert[1]
        )
        self._logs_ws_url = f"wss://{self.address.strip('/')}:{self.port}/logs"
        self._logs_queues = []
        self._logs_bg_thread = threading.Thread(target=self._bg_fetch_logs, daemon=True)

        self._api = None
        self._started = False

        # Elapsed-time caches must not depend on wall-clock adjustments.
        self._connected_cache = None
        self._connected_cache_time = 0
        self._started_cache = None
        self._started_cache_time = 0
        self._cache_ttl = 150
        self._error_cache_ttl = 150
        self._state_lock = threading.RLock()
        self._status_lock = threading.Lock()
        self._lifecycle_lock = threading.RLock()
        self._state_generation = 0

    def _prepare_config(self, config: XRayConfig):
        for inbound in config.get("inbounds", []):
            streamSettings = inbound.get("streamSettings") or {}
            tlsSettings = streamSettings.get("tlsSettings") or {}
            certificates = tlsSettings.get("certificates") or []
            for certificate in certificates:
                if certificate.get("certificateFile"):
                    with open(certificate["certificateFile"]) as file:
                        certificate["certificate"] = [
                            line.strip() for line in file.readlines()
                        ]
                        del certificate["certificateFile"]

                if certificate.get("keyFile"):
                    with open(certificate["keyFile"]) as file:
                        certificate["key"] = [line.strip() for line in file.readlines()]
                        del certificate["keyFile"]

        return config

    def make_request(self, path: str, timeout: int, **params):
        try:
            res = self.session.post(
                self._rest_api_url + path,
                timeout=timeout,
                json={"session_id": self._session_id, **params},
            )
            data = res.json()
        except Exception as e:
            exc = NodeAPIError(0, str(e))
            raise exc

        if res.status_code == 200:
            return data
        else:
            exc = NodeAPIError(res.status_code, data["detail"])
            raise exc

    def _update_status_cache(self, connected=None, started=None):
        with self._state_lock:
            self._state_generation += 1
            now = time.monotonic()
            self._connected_cache = connected
            self._connected_cache_time = now
            self._started_cache = started
            self._started_cache_time = now

    def _cached_status(self, field):
        # Coalesce concurrent expired-cache reads for this node.
        with self._status_lock:
            with self._state_lock:
                if not self._session_id:
                    return False
                value = getattr(self, "_" + field + "_cache")
                checked = getattr(self, "_" + field + "_cache_time")
                ttl = self._cache_ttl if value else self._error_cache_ttl
                if value is not None and time.monotonic() - checked < ttl:
                    return value
                generation = self._state_generation
                session_id = self._session_id

            try:
                if field == "connected":
                    self.make_request("/ping", timeout=30)
                    value = True
                else:
                    value = bool(self.make_request("/", timeout=30).get("started", False))
            except NodeAPIError as exc:
                value = False
                logger.debug("Node %s %s probe failed: status=%s detail=%s",
                             self.address, field, exc.status_code, exc.detail)

            with self._state_lock:
                if (generation != self._state_generation or
                        session_id != self._session_id):
                    # An older probe cannot overwrite a completed lifecycle transition.
                    return getattr(self, "_" + field + "_cache") is True
                previous = getattr(self, "_" + field + "_cache")
                setattr(self, "_" + field + "_cache", value)
                setattr(self, "_" + field + "_cache_time", time.monotonic())
            if previous != value:
                logger.info("Node %s %s status: %s", self.address, field, value)
            return value

    @property
    def connected(self):
        return self._cached_status("connected")

    @property
    def started(self):
        return self._cached_status("started")

    @property
    def api(self):
        if not self._session_id:
            raise ConnectionError("Node is not connected")

        if not self._api:
            if self._started is True:
                self._api = XRayAPI(
                    address=self.address,
                    port=self.api_port,
                    ssl_cert=self._node_cert.encode(),
                    ssl_target_name="Gozargah",
                )
            else:
                raise ConnectionError("Node is not started")

        return self._api

    def connect(self):
        with self._lifecycle_lock:
            self._update_status_cache()
            self._started = False
            self._api = None
            try:
                self._node_cert = ssl.get_server_certificate((self.address, self.port))
                self._node_certfile = string_to_temp_file(self._node_cert)
                self.session.verify = self._node_certfile.name
                res = self.make_request("/connect", timeout=30)
                self._session_id = res["session_id"]
                self._update_status_cache(connected=True)
            except Exception:
                self._session_id = None
                self._update_status_cache(connected=False, started=False)
                raise

    def disconnect(self):
        with self._lifecycle_lock:
            try:
                if self._session_id:
                    self.make_request("/disconnect", timeout=30)
            finally:
                self._session_id = None
                self._started = False
                self._api = None
                self._update_status_cache(connected=False, started=False)

    def get_version(self):
        res = self.make_request("/", timeout=30)
        return res.get("core_version")

    def start(self, config: XRayConfig):
        with self._lifecycle_lock:
            if not self.connected:
                self.connect()
            self._update_status_cache(connected=True)
            try:
                config = self._prepare_config(deepcopy(config))
                try:
                    res = self.make_request("/start", timeout=60, config=config.to_json())
                except NodeAPIError as exc:
                    if exc.detail == "Xray is started already":
                        return self.restart(config)
                    raise
                self._wait_for_api()
                self._update_status_cache(connected=True, started=True)
                return res
            except Exception:
                self._started = False
                self._api = None
                self._update_status_cache()
                raise

    def _wait_for_api(self):
        self._started = True
        self._api = XRayAPI(
            address=self.address,
            port=self.api_port,
            ssl_cert=self._node_cert.encode(),
            ssl_target_name="Gozargah",
        )
        try:
            grpc.channel_ready_future(self._api._channel).result(timeout=35)
        except grpc.FutureTimeoutError:
            raise ConnectionError("Failed to connect to node's API")

    def stop(self):
        if not self.connected:
            self.connect()

        self.make_request("/stop", timeout=35)
        self._api = None
        self._started = False

    def restart(self, config: XRayConfig):
        with self._lifecycle_lock:
            if not self.connected:
                self.connect()
            self._update_status_cache(connected=True)
            try:
                config = self._prepare_config(deepcopy(config))
                res = self.make_request("/restart", timeout=60, config=config.to_json())
                self._wait_for_api()
                self._update_status_cache(connected=True, started=True)
                return res
            except Exception:
                self._started = False
                self._api = None
                self._update_status_cache()
                raise

    def _bg_fetch_logs(self):
        while self._logs_queues:
            try:
                websocket_url = (
                    f"{self._logs_ws_url}?session_id={self._session_id}&interval=0.7"
                )
                self._ssl_context.load_verify_locations(self.session.verify)
                ws = create_connection(
                    websocket_url, sslopt={"context": self._ssl_context}, timeout=2
                )
                while self._logs_queues:
                    try:
                        logs = ws.recv()
                        for buf in self._logs_queues:
                            buf.append(logs)
                    except WebSocketConnectionClosedException:
                        break
                    except WebSocketTimeoutException:
                        pass
                    except Exception:
                        pass
            except Exception:
                pass
            time.sleep(2)

    @contextmanager
    def get_logs(self):
        try:
            buf = deque(maxlen=100)
            self._logs_queues.append(buf)

            if not self._logs_bg_thread.is_alive():
                try:
                    self._logs_bg_thread.start()
                except RuntimeError:
                    self._logs_bg_thread = threading.Thread(
                        target=self._bg_fetch_logs, daemon=True
                    )
                    self._logs_bg_thread.start()

            yield buf

        finally:
            try:
                self._logs_queues.remove(buf)
            except ValueError:
                pass
            del buf

_node_operations_lock = Lock()
_node_operations = {}


def get_node_ids():
    # An admitted worker may not have inserted its new runtime object yet.
    with _node_operations_lock:
        return sorted(set(xray.nodes) | set(_node_operations))


def _request_node_operation(node_id, action, config, health_check):
    with _node_operations_lock:
        if health_check and node_id in _node_operations:
            return

    # Preserve the exact requested config without sharing TLS preparation mutations.
    request = (action, deepcopy(config) if config is not None else None)
    with _node_operations_lock:
        operation = _node_operations.get(node_id)
        if operation is not None:
            if not health_check:
                operation["pending"] = request
            return
        operation = {"pending": request}
        _node_operations[node_id] = operation
        worker = Thread(target=_run_node_operations, args=(node_id, operation), daemon=True)
        try:
            worker.start()
        except Exception:
            del _node_operations[node_id]
            raise


def _run_node_operations(node_id, operation):
    try:
        while True:
            with _node_operations_lock:
                action, config = operation["pending"]
                operation["pending"] = None
            try:
                _perform_node_operation(node_id, action, config)
            except Exception:
                # Also recover from failures before a node/DB object can be obtained.
                logger.exception("Node %s lifecycle worker failed", node_id)
            with _node_operations_lock:
                if operation["pending"] is None:
                    if _node_operations.get(node_id) is operation:
                        del _node_operations[node_id]
                    return
    finally:
        with _node_operations_lock:
            if _node_operations.get(node_id) is operation:
                del _node_operations[node_id]


def _perform_node_operation(node_id, action, config):
    with GetDB() as db:
        dbnode = crud.get_node_by_id(db, node_id)
    if not dbnode or dbnode.status == NodeStatus.disabled:
        return

    node = None
    try:
        node = xray.nodes.get(node_id)
        if node is None or not node.connected:
            node = add_node(dbnode)
            action = "connect"

        if config is None:
            config = xray.config.include_db_users()

        if action == "connect":
            _change_node_status(node_id, NodeStatus.connecting)
            logger.info("Connecting to node %s (%s)", node_id, dbnode.name)
            node.start(config)
            version = node.get_version()
        else:
            logger.info("Restarting Xray core of node %s (%s)", node_id, dbnode.name)
            node.restart(config)
            version = dbnode.xray_version

        if xray.nodes.get(node_id) is node:
            _change_node_status(node_id, NodeStatus.connected, version=version)
            logger.info("Node %s lifecycle operation %s completed", node_id, action)
    except Exception as exc:
        # A removed/replaced node is no longer owned by this operation.
        if node is not None and xray.nodes.get(node_id) is node:
            _change_node_status(node_id, NodeStatus.error, message=str(exc))
            logger.exception("Node %s lifecycle operation %s failed", node_id, action)
            try:
                node.disconnect()
            except Exception:
                logger.exception("Node %s cleanup after %s failed", node_id, action)


def connect_node(node_id, config=None, *, health_check=False):
    _request_node_operation(node_id, "connect", config, health_check)


def restart_node(node_id, config=None, *, health_check=False):
    _request_node_operation(node_id, "restart", config, health_check)


__all__ = [
    "add_user",
    "remove_user",
    "add_node",
    "remove_node",
    "connect_node",
    "restart_node",
]

def core_health_check():
    config = None

    # main core
    if not xray.core.started:
        if not config:
            config = xray.config.include_db_users()
        xray.core.restart(config)

    # nodes' core
    for node_id, node in list(xray.nodes.items()):
        if node.connected:
            try:
                assert node.started
                node.api.get_sys_stats(timeout=2)
            except (ConnectionError, xray_exc.XrayError, AssertionError):
                if not config:
                    config = xray.config.include_db_users()
                xray.operations.restart_node(node_id, config, health_check=True)

        if not node.connected:
            if not config:
                config = xray.config.include_db_users()
            xray.operations.connect_node(node_id, config, health_check=True)

@router.post("/core/restart", responses={403: responses._403})
def restart_core(admin: Admin = Depends(Admin.check_sudo_admin)):
    """Restart the core and all connected nodes."""
    with _core_config_lock:
        startup_config = xray.config.include_db_users()
        xray.core.restart(startup_config)

        for node_id in xray.operations.get_node_ids():
            xray.operations.restart_node(node_id, startup_config)

        return {}

@router.put("/core/config", responses={403: responses._403})
def modify_core_config(
    payload: dict, admin: Admin = Depends(Admin.check_sudo_admin)
) -> dict:
    """Modify the core configuration and restart the core."""
    with _core_config_lock:
        try:
            config = XRayConfig(payload, api_port=xray.config.api_port)
        except ValueError as err:
            raise HTTPException(status_code=400, detail=str(err))

        xray.config = config
        with open(XRAY_JSON, "w") as f:
            f.write(json.dumps(payload, indent=4))

        startup_config = xray.config.include_db_users()
        xray.core.restart(startup_config)
        for node_id in xray.operations.get_node_ids():
            xray.operations.restart_node(node_id, startup_config)

        xray.hosts.update()

        return payload
